main.script:
document.addEventListener('DOMContentLoaded', function() {
    // Pack size price sync
    document.querySelectorAll('.inno-weight-select').forEach(function(select) {
        select.addEventListener('change', function(e) {
            var card = e.target.closest('.inno-product-card');
            if (!card) return;
            var weight = e.target.value;
            var price = card.getAttribute('data-price-' + weight);
            if (price) {
                var display = card.querySelector('.inno-price-display');
                if (display) {
                    var formatted = Number(price).toLocaleString('vi-VN') + ' đ';
                    display.textContent = formatted;
                }
            }
        });
    });

    // Add to cart mock trigger / alert
    document.querySelectorAll('.inno-add-cart-btn').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            var card = btn.closest('.inno-product-card');
            var title = card ? card.querySelector('h3').textContent.trim() : 'Sản phẩm';
            var weightSelect = card ? card.querySelector('.inno-weight-select') : null;
            var weight = weightSelect ? weightSelect.value + 'g' : '250g';
            var grindSelect = card ? card.querySelector('.inno-grind-select') : null;
            var grind = grindSelect ? grindSelect.options[grindSelect.selectedIndex].text : '';

            var originalText = btn.innerHTML;
            btn.innerHTML = ' Đã Thêm!';
            btn.classList.remove('btn-primary');
            btn.classList.add('btn-success');
            setTimeout(function() {
                btn.innerHTML = originalText;
                btn.classList.remove('btn-success');
                btn.classList.add('btn-primary');
            }, 2000);
        });
    });
});
